import sys

def decode_brute(s):
    if not s: return 0
    n = len(s)
    from functools import lru_cache
    @lru_cache(None)
    def dfs(i):
        if i == n: return 1
        if s[i] == '0': return 0
        res = dfs(i + 1)
        if i + 1 < n and 10 <= int(s[i:i+2]) <= 26:
            res += dfs(i + 2)
        return res
    return dfs(0)

if __name__ == '__main__':
    s = sys.stdin.readline().rstrip()
    print(decode_brute(s))
